                if not (string.find(assassinraces, actor.race)) then
                    actor:send("- <red>Assassin</>")
                    actor:send("</>   <cyan>(This class is for evil characters only)</>_")
                end
                if not (string.find(bardraces, actor.race)) then
                    actor:send("- <b:magenta>Bard</>_")
