  (4, 20, $trig$-- Converted from DG Script #420: Doom Entrance progress journal
-- Original: OBJECT trigger, flags: LOOK, probability: 100%
local _return_value = true  -- Default: allow action
if string.find(arg, "doom entrance") or string.find(arg, "the planes of doom") or string.find(arg, "planes of doom") or string.find(arg, "doom_entrance") or string.find(arg, "the_planes_of_doom") or string.find(arg, "planes_of_doom") or string.find(arg, "planes") then
    if actor.level >= 85 then
        _return_value = true
        local stage = actor:get_quest_stage("doom_entrance")
        actor:send("<b:u:green>The Planes of Doom</>")
        actor:send("Minimum Level: 85")
        actor:send("- This quest begins a storyline intended for characters of level 95+")
        local status
        if actor:get_has_completed("doom_entrance") then
            status = "Completed!"
        elseif (stage or 0) > 0 then
            status = "In Progress"
        else
            status = "Not Started"
        end
        actor:send("<cyan>Status: " .. tostring(status) .. "</>_")
        if stage > 0 and not actor:get_has_completed("doom_entrance") then
            -- switch on stage
            local master
            local task
            do
                local _sw1 = string.lower(tostring(stage or ""))
                if tonumber(_sw1) == 1 then
                    master = mobiles.template(484, 11).name
                    task = "Track down the White Hart in the Eldorian Foothills and hold the bloody rag in its presence"
                elseif tonumber(_sw1) == 2 then
                    master = mobiles.template(484, 11).name
                    task = "Slay the White Hart and bring its antlers to " .. tostring(master)
                elseif tonumber(_sw1) == 3 then
                    master = mobiles.template(484, 10).name
                    task = "Slay Rhalean's Evil Sister, trapped deep underground"
                elseif tonumber(_sw1) == 4 then
                    master = mobiles.template(484, 10).name
                    task = "Return to " .. tostring(master)
                elseif tonumber(_sw1) == 5 then
                    master = mobiles.template(484, 12).name
                    task = "Drop the vial of sunlight before a mockery of the sun in a place steeped in darkness"
                elseif tonumber(_sw1) == 6 then
                    master = mobiles.template(484, 12).name
                    task = "Return to " .. tostring(master)
                end
            end
            actor:send("Quest Master: " .. tostring(master))
            actor:send("</>")
            actor:send(tostring(task) .. ".")
        end
    end
end
