                        actor:send("- " .. tostring(objects.template(590, 28).name))
                    end
                    if trinket == 1 then
                        actor:send("- " .. tostring(objects.template(590, 29).name))
                    end
                    if earring == 1 then
                        actor:send("- " .. tostring(objects.template(590, 30).name))
                    end
                end
