                    hunt = "2 Xeg-Yi and " .. tostring(mobiles.template(533, 8).name)
                    local mob2 = 53411
                    local mob1 = 53308
                    item = objects.template(533, 7).name
                elseif tonumber(_sw1) == 7 then
                    item = objects.template(533, 7).name
