                    item = objects.template(520, 1).name
                elseif tonumber(_sw1) == 12 then
                    actor:send("Destroy Norisent!")
                    return _return_value
                end
            end
        end
        if stage == 4 or stage == 6 or stage == 8 or stage == 10 then
