                    if target3 then
                        actor:send("- " .. "%get.mob_shortdesc[%mob3%]%")
                    end
                end
            end
            if (stage ~= 6 and (not target1 or not target2 or not target3)) or (stage == 6 and (not target1 or target2 < 2)) then
                actor:send("</>")
