  -- data/triggers/030/030_09_erasmus_responds_to_charm_person.lua
  (30, 9, $trig$-- Converted from DG Script #3009: Erasmus responds to "charm person"
-- Original: MOB trigger, flags: SPEECH_TO, probability: 100%
-- DG word list (num_arg 100): the speech must contain one of these as a whole word or phrase.
local speech_padded = " " .. string.lower(speech) .. " "
local speech_hit = false
for _, w in ipairs({"charm"}) do
    if string.find(speech_padded, "[%s%p]" .. string.gsub(w, "%p", "%%%0") .. "[%s%p]") then
        speech_hit = true
        break
    end
end
if not speech_hit then
    return true  -- None of the listed words
end

wait(2)
if string.find(actor.class, "illusionist") then
    if actor:get_skill("charm person") >= 1000 then
        self:say("A nice spell, isn't it?  I hope you're enjoying it.")
    elseif actor.level < 17 then
        self:say("Ah, charm person.  A powerful spell, capable of great evil - or good.")
        wait(2)
        self:say("Come back when you have a bit more experience, and I'll teach it to you.")
    else
        self:say("Oh, the charm person spell.  You're ready to learn that one!")
        wait(2)
        self:say("Stand still there while I teach you.")
        wait(2)
        self:emote("launches into a marathon of lectures and speeches about diverse arcana.")
        wait(5)
        self:emote("is still spewing forth obscure knowledge at a furious rate!")
        wait(5)
        self:emote("seems to be winding down, as if the lesson were almost over.")
        wait(5)
        if actor.room == self.room then
            self:say("I'm impressed with your attentiveness, " .. tostring(actor.name) .. ".")
            wait(3)
            self:say("I can see that you've learned charm person rather well.")
            skills.set_level(actor, "charm person", 1000)
        else
            self:say("Eh?  Where did " .. tostring(actor.name) .. " go?  Must not have a thirst for knowledge!")
        end
    end
elseif string.find(actor.class, "sorcerer") then
    if actor:get_skill("charm person") >= 1000 then
        self:command("gasp")
        wait(3)
        self:say("What's this?  An ordinary sorcerer with charm person?!")
        wait(5)
        self:say("Will wonders never cease!")
        wait(5)
        self:command("shake")
    else
        self:say("Don't look at me!  I'm a legendary teacher, but some things are just beyond me!")
        wait(5)
        self:say("You sorcerers require extra help learning this... rather simple spell.")
        wait(5)
        self:say("And you'll get none of it for me, because I have better things to do.")
    end
else
    self:command("sigh")
    wait(3)
    self:say("Yes, yes, a wonderful spell, how incredible we illusionists are, certainly.")
    wait(3)
    self:command("roll")
    wait(3)
    self:say("Why don't you go bash some poor rodents' heads in.  Or whatever it is you do.")
end$trig$, '1deddb960d2808e18bf1c990806e2705'),
  -- data/triggers/030/030_151_intercity_transport_questmasters_talk.lua
  (30, 151, $trig$-- Converted from DG Script #3151: Intercity transport questmasters talk
-- Original: MOB trigger, flags: SPEECH_TO, probability: 100%
-- DG word list (num_arg 100): the speech must contain one of these as a whole word or phrase.
local speech_padded = " " .. string.lower(speech) .. " "
local speech_hit = false
for _, w in ipairs({"yes", "yes", "help", "help", "tell"}) do
    if string.find(speech_padded, "[%s%p]" .. string.gsub(w, "%p", "%%%0") .. "[%s%p]") then
        speech_hit = true
        break
    end
end
if not speech_hit then
    return true  -- None of the listed words
end

if actor:get_quest_stage("intercity_transport") == 0 then
    actor:start_quest("intercity_transport")
end
-- switch on self.id
local myname = "elf"
local dest = "Mielikki"
if (self.zone_id == 30 and self.id == 151) or (self.zone_id == 300 and self.id == 75) then
    myname = "barbarian"
    dest = "Ickle"
elseif (self.zone_id == 30 and self.id == 152) then
    myname = "dwarf"
    dest = "Anduin"
elseif (self.zone_id == 300 and self.id == 74) then
    myname = "drow"
    dest = "Anduin"
elseif (self.zone_id == 300 and self.id == 76) then
    myname = "human"
    dest = "Mielikki"
elseif (self.zone_id == 300 and self.id == 77) then
    myname = "orc"
    dest = "Ogakh"
elseif (self.zone_id == 30 and self.id == 150) then
    -- legacy: questmaster 3150 had no myname/dest; bail before sending speech
    return true
end
wait(0.3)
if actor.level < 16 then
    actor:send("<blue>The " .. tostring(myname) .. " tells you, 'As long as you're under level 16, I can transport you to " .. tostring(dest) .. ".'</>")
    actor:send("<blue>The " .. tostring(myname) .. " tells you, 'Just ask me 'transport', and I'll send you.'</>")
else
    actor:send("<blue>The " .. tostring(myname) .. " tells you, 'I send people below level 16 to " .. tostring(dest) .. ".'</>")
    actor:send("<blue>The " .. tostring(myname) .. " tells you, 'Unfortunately, you are too powerful.'</>")
end$trig$, '2611588a14288431af151264cd52cb6f'),
  -- data/triggers/030/030_154_transport_agents_ask.lua
  (30, 154, $trig$-- Converted from DG Script #3154: Transport agents ask
-- Original: MOB trigger, flags: SPEECH_TO, probability: 100%
-- DG word list (num_arg 100): the speech must contain one of these as a whole word or phrase.
local speech_padded = " " .. string.lower(speech) .. " "
local speech_hit = false
for _, w in ipairs({"transport"}) do
    if string.find(speech_padded, "[%s%p]" .. string.gsub(w, "%p", "%%%0") .. "[%s%p]") then
        speech_hit = true
        break
    end
end
if not speech_hit then
    return true  -- None of the listed words
end

-- This is the ask trigger for intercity transport questmasters.
-- It allows level 1-15 people to get transport by asking to
-- Anduin, Ickle, or Mielikki.
-- Much of this trigger is a copy of 3152.
-- ******************
-- * GENERAL SETUP **
-- ******************
local minlevel = 1
local maxlevel = 15
-- switch on self.id
local myname = "elf"
local dest_room = 3016
local dsname = "Mielikki"
if (self.zone_id == 30 and self.id == 151) or (self.zone_id == 300 and self.id == 75) then
    -- barbarian, sends to Ickle
    myname = "barbarian"
    dest_room = 10046
    dsname = "Ickle"
elseif (self.zone_id == 30 and self.id == 152) then
    -- dwarf, sends to Anduin
    myname = "dwarf"
    dest_room = 6015
    dsname = "Anduin"
elseif (self.zone_id == 300 and self.id == 74) then
    myname = "drow"
    dest_room = 6015
    dsname = "Anduin"
elseif (self.zone_id == 300 and self.id == 76) then
    myname = "human"
    dest_room = 3016
    dsname = "Mielikki"
elseif (self.zone_id == 300 and self.id == 77) then
    myname = "orc"
    dest_room = 30115
    dsname = "Ogakh"
elseif (self.zone_id == 30 and self.id == 150) then
    -- legacy: questmaster 3150 had no agent record; bail
    return true
end
wait(0.4)
-- **************************
-- * Check for eligibility **
-- **************************
if actor.level > 99 then
    self:command("eyebrow " .. tostring(actor.name))
    actor:send("<blue>The " .. tostring(myname) .. " tells you, 'Just goto " .. tostring(dest_room) .. ".'")
    return _return_value
elseif minlevel > actor.level then
    self:command("shake")
    actor:send("<blue>The " .. tostring(myname) .. " tells you, 'You are not experienced enough to go to " .. tostring(dsname) .. ".'</>")
    return _return_value
elseif actor.level > maxlevel then
    self:command("eyebrow " .. tostring(actor.name))
    actor:send("<blue>The " .. tostring(myname) .. " tells you, 'You are too powerful for me to transport.'</>")
    return _return_value
end
-- **************************
-- * Set origination color **
-- **************************
-- The color says where they came from.
-- It is seen by anyone standing at the destination.
local dcolor
if self.room == 3016 then
    -- Mielikki - GREEN
    dcolor = "<green>green</>"
elseif self.room == 6015 then
    -- Anduin - RED
    dcolor = "<red>red</>"
elseif self.room == 30115 then
    -- Ogakh - GRAY
    dcolor = "<b:black>gray</>"
else
    -- Ickle - BLUE
    dcolor = "<blue>blue</>"
end
-- **********************
-- * Perform transport **
-- **********************
self.room:send_except(actor, tostring(self.name) .. " nods briefly to " .. tostring(actor.name) .. ".")
actor:send(tostring(self.name) .. " nods briefly to you.")
wait(0.4)
self.room:send_except(actor, tostring(self.name) .. " makes a magical gesture at " .. tostring(actor.name) .. ".")
actor:send(tostring(self.name) .. " makes a magical gesture at you.")
self.room:send_except(actor, tostring(actor.name) .. " disappears in a cloud of gray smoke.")
actor:teleport(get_room(math.floor(dest_room / 100), dest_room % 100))
get_room(math.floor(dest_room / 100), dest_room % 100):at(function()
    self.room:send_except(actor, tostring(actor.name) .. " arrives in a cloud of " .. tostring(dcolor) .. " smoke.")
end)
