  -- data/triggers/051/051_12_monk_subclass_quest_arre_receieve.lua
  (51, 12, $trig$-- Converted from DG Script #5112: monk_subclass_quest_arre_receieve
-- Original: MOB trigger, flags: RECEIVE, probability: 100%
--
-- Receive trigger filtered to the bronze sash (object 16110 in legacy
-- vnum, no longer mapped here -- DG scoped this trigger to that object).
-- Stage gating:
--   1 / 2 - Quest not far enough along (player still owes the "fiend"
--           keyword); reject playfully.
--   3     - Player got the sash but didn't trigger the get hook (i.e.
--           handed off / stole it); refuse and call them out.
--   4     - Recover stage: complete the subclass quest.
--   else  - Stage 0/nil/5+: thank them, but no quest progress.
-- After all branches, junk the sash.
wait(0.2)
local stage = actor:get_quest_stage("monk_subclass")
if stage == 1 or stage == 2 then
    actor:send(self.name .. " says, 'Funny, I don't even remember telling you what you were questing for.'")
elseif stage == 3 then
    -- Player has the sash but never picked it up themselves.
    actor:send(self.name .. " says, 'How on earth did you get me this?  Did you come by it through your own means?'")
    self:command("eye " .. actor.name)
    self:emote("shakes her head.")
    wait(2)
    actor:send(self.name .. " says, 'I cannot help those who cheat themselves.'")
elseif stage == 4 then
    self:emote("cheers wildly, dancing all around the room.")
    wait(0.3)
    self:emote("pants heavily for a moment calming down.")
    wait(0.1)
    self:command("shake " .. actor.name)
    actor:send(self.name .. " says, 'Wonderful, this shows your true dedication to helping one of the brotherhood.'")
    self:command("grin")
    wait(0.2)
    actor:send(self.name .. " says, 'Type <b:black>'subclass'</> to proceed.'")
    actor:complete_quest("monk_subclass")
else
    actor:send(self.name .. " says, 'What a wonderful sash, thank you.'")
    wait(1)
    actor:send(self.name .. " says, 'Shame you were not questing for me, this is a great prize you have given me.'")
end
self:destroy_item("sash")$trig$, 'a81e0f98e56150c6ff33e74aa8c220db'),
  -- data/triggers/052/052_02_pyromancer_subclass_quest_emmath_greet.lua
  (52, 2, $trig$wait(0.2)
-- TODO: type_wand greet branch removed pending quest schema rework.
local stage = actor:get_quest_stage("pyromancer_subclass")
-- switch on stage
if stage == 1 then
    actor:send(tostring(self.name) .. " says, 'Come back to try again have you?  Only the best and most motivated of mages will complete the quest I lay before you.'")
    self:command("smile")
    wait(2)
    actor:send(tostring(self.name) .. " says, 'However, I am sure it is in you, if it is truly your desire, to complete this <b:red>quest</> and become a pyromancer.'")
elseif stage == 2 then
    actor:send(tostring(self.name) .. " says, 'Are you ready to finish listening now?  I once controlled all three parts of the flame: <b:white>White</>, <blue>Gray</>, and <b:black>Black</>.'")
    wait(2)
    self:command("frown")
    actor:send(tostring(self.name) .. " says, 'But one of them was taken from my <b:red>control</>.'")
    wait(1)
    self:command("sigh")
elseif stage == 3 or stage == 4 then
    actor:send(tostring(self.name) .. " says, 'Do you have the " .. tostring(actor:get_quest_var("pyromancer_subclass:part")) .. " flame?  Give it here!'")
else
    if string.find(actor.class, "sorcerer") then
        if actor.race == "dragonborn_frost" or actor.race == "arborean" then
            return true
        else
            if actor.level >= 10 and actor.level <= 45 then
                self.room:send("Emmath Firehand's glowing eyes flash brightly for a moment.")
                actor:send(tostring(self.name) .. " says, 'Some love the life of <b:red>flame</>.  Do you?'")
                self:emote("flicks a grin around the room.")
            elseif string.find(actor.class, "sorcerer") and actor.level < 10 then
                self:emote("stares in amazement at " .. tostring(actor.name) .. ".")
                actor:send(tostring(self.name) .. " says, 'I have no idea how you found me but you are far too inexperienced to be in these tunnels in the first place, and even less to ask for my guidance.'")
            end
        end
    end
end$trig$, 'ed2b3f43a27014bb475c0b8305645cc6'),
  -- data/triggers/052/052_05_pyromancer_subclass_quest_emmath_speech3.lua
  (52, 5, $trig$-- DG word list (num_arg 1): the speech must contain one of these as a whole word or phrase.
local speech_padded = " " .. string.lower(speech) .. " "
local speech_hit = false
for _, w in ipairs({"quest", "quest?"}) do
    if string.find(speech_padded, "[%s%p]" .. string.gsub(w, "%p", "%%%0") .. "[%s%p]") then
        speech_hit = true
        break
    end
end
if not speech_hit then
    return true  -- None of the listed words
end

wait(0.2)
if actor:get_quest_stage("pyromancer_subclass") == 1 then
    actor:advance_quest("pyromancer_subclass")
    local part
    if actor.alignment >= 350 then
        part = "white"
    elseif actor.alignment <= -350 then
        part = "black"
    else
        part = "gray"
    end
    actor:set_quest_var("pyromancer_subclass", "part", part)
    actor:send(tostring(self.name) .. " says, 'I seem to have a problem now, because some time ago...'")
    self:emote("sighs, looking troubled.")
    wait(2)
    actor:send(tostring(self.name) .. " says, 'It is just...'")
    wait(1)
    actor:send(tostring(self.name) .. " says, 'Well, part of the essence of fire is no longer under my power.'")
    self:emote("shakes his head sadly.")
    wait(2)
    actor:send(tostring(self.name) .. " says, 'I once controlled all three parts of the flame: <b:white>White</>, <blue>Gray</>, and <b:black>Black</>.'")
    wait(2)
    self:command("frown")
    actor:send(tostring(self.name) .. " says, 'But one of them was taken from my <b:red>control</>.'")
    wait(1)
    self:command("sigh")
elseif actor:get_quest_stage("pyromancer_subclass") > 1 then
    self:command("grumble")
    wait(1)
    actor:send(tostring(self.name) .. " says, 'I already told you about the quest.'")
    wait(2)
    actor:send(tostring(self.name) .. " says, 'Part of the flame is no longer under my <b:red>control</>.  You should remember that much.'")
end$trig$, 'b5b0e56653ac9fddb152ca4114f4cd7e'),
  -- data/triggers/052/052_06_pyromancer_subclass_quest_emmath_speech4.lua
