    if _sw1 == "s" or _sw1 == "st" or _sw1 == "sta" or _sw1 == "star" then
        _return_value = true
        return _return_value
    end
end
if player1 then
    if player2 then
        actor:send(tostring(player1.name) .. " and " .. tostring(player2.name) .. " are already playing ConnectFour!")
