  -- data/triggers/120/120_99_twisted_sorrow_status_tracker.lua
  (120, 99, $trig$-- Speech keywords: progress
local speech_lower = string.lower(speech)
if not string.find(speech_lower, "progress") then
    return true  -- No matching keywords
end

-- Each entry: { tree_room_local_id, quest_var_suffix }
-- Quest var key matches the legacy 5-digit room vnum used by trigger 120-3.
local trees = {
    { 16, "12016" },  -- Tree of Luck
    { 17, "12017" },  -- Tree of Reverence
    { 18, "12018" },  -- Tree of Self-Reliance
    { 14, "12014" },  -- Tree of Nimbleness
    { 46, "12046" },  -- Tree of Kindness
}

wait(0.4)
local stage = actor:get_quest_stage("twisted_sorrow")
if stage > 1 then
    self:command("smile " .. actor.name)
    wait(1)
    self:say("The trees are satisfied, my friend.")
    return true
end

if stage ~= 1 then
    return true
end

self:say("Bring drink to awaken the trees from the corruption.")

local any_satisfied = false
for _, t in ipairs(trees) do
    if actor:get_quest_var("twisted_sorrow:satisfied_tree:" .. t[2]) == 1 then
        any_satisfied = true
        break
    end
end

if any_satisfied then
    self.room:send("You have already awakened the following trees:")
    for _, t in ipairs(trees) do
        if actor:get_quest_var("twisted_sorrow:satisfied_tree:" .. t[2]) == 1 then
            self.room:send("- <b:black>" .. get_room(120, t[1]).name .. "</>")
        end
    end
end

self.room:send("Offerings are still needed for:")
for _, t in ipairs(trees) do
    if actor:get_quest_var("twisted_sorrow:satisfied_tree:" .. t[2]) ~= 1 then
        self.room:send("- <green>" .. get_room(120, t[1]).name .. "</>")
    end
end
self.room:send("</>")
self:say("Say <b:cyan>\"follow me\"</> when you have an offering to present.")$trig$, '488c36d28d44c234af42da05d1778056'),
  -- data/triggers/123/123_01_priestess_speech1.lua
  (123, 1, $trig$-- Converted from DG Script #12301: priestess_speech1
-- Original: MOB trigger, flags: SPEECH, num_arg: 1 (DG word-list mode, not a probability)

-- DG word list (num_arg 1): the speech must contain one of these as a whole word or phrase.
local speech_padded = " " .. string.lower(speech) .. " "
local speech_hit = false
for _, w in ipairs({"assist", "assistance", "assist?", "assistance?", "how", "what"}) do
    if string.find(speech_padded, "[%s%p]" .. string.gsub(w, "%p", "%%%0") .. "[%s%p]") then
        speech_hit = true
        break
    end
end
if not speech_hit then
    return true  -- None of the listed words
end
if string.find(speech, "assist") or string.find(speech, "assistance") or string.find(speech, "assist?") or string.find(speech, "assistance?") or string.find(speech, "how can i help?") or string.find(speech, "how can i assist?") or string.find(speech, "what can i do?") or string.find(speech, "what can i do to assist?") then
    wait(0.2)
    self.room:send(tostring(self.name) .. " says, 'Our coven came to this megalith to perform the <b:white>Great Rite of Invocation</> and summon our faerie goddess The Great Mother, the Lady of the Stars.'")
end$trig$, 'ccf39ddf7cf41e450eafe9267ec4de41'),
