            self.room:spawn_mobile(123, 21)
            local shoggoth = self.room:find_actor("shoggoth")
            if shoggoth then shoggoth:command("kill " .. tostring(actor.name)) end
            -- Clear all the bads, in case you try again later
            for slot = 1, 4 do
