  -- data/triggers/519/519_80_academy_recruiter_speech_resume.lua
  (519, 80, $trig$-- Converted from DG Script #51980: academy_recruiter_speech_resume
-- Original: MOB trigger, flags: SPEECH, probability: 100%

-- Speech keywords: resume
local speech_lower = string.lower(speech)
if not (string.find(string.lower(speech), "resume")) then
    return true  -- No matching keywords
end
wait(0.2)
local stage = actor:get_quest_stage("school")
if actor:get_has_completed("school") or stage == 0 then
    return true
end
-- Declared up front: the DG `set` variables are read after the switch below.
local lesson
local holding
local direction
-- switch on actor:get_quest_stage("school")
if stage == 1 then
    lesson = "<b:yellow>COMMUNICATION</>, <b:yellow>GEAR</>, and <b:yellow>EXPLORATION</>"
    holding = 0
    direction = "east"
    self:command("unlock gates")
    self:command("open gates")
elseif stage == 2 then
    lesson = "<b:yellow>HIT POINTS</> and <b:yellow>SCORE</>"
    holding = 9
    direction = "east"
elseif stage == 3 or stage == 4 then
    if stage == 3 then
        lesson = "<b:yellow>COMBAT</>"
    elseif stage == 4 then
        lesson = "<b:yellow>LOOT</> and <b:yellow>TOGGLES</>"
    end
    -- switch on actor.class
    local class_lower = string.lower(tostring(actor.class or ""))
    if class_lower == "rogue" or class_lower == "thief" or class_lower == "assassin" or class_lower == "mercenary" or class_lower == "bard" then
        direction = "down"
    elseif class_lower == "sorcerer" or class_lower == "cryomancer" or class_lower == "pyromancer" or class_lower == "necromancer" or class_lower == "illusionist" then
        direction = "south"
    elseif class_lower == "cleric" or class_lower == "priest" or class_lower == "diabolist" or class_lower == "druid" then
        direction = "east"
    elseif class_lower == "warrior" or class_lower == "paladin" or class_lower == "anti-paladin" or class_lower == "ranger" or class_lower == "monk" or class_lower == "berserker" then
        direction = "north"
    else
        actor:send(tostring(self.name) .. " tells you, 'I don't know how you got to this point.  Please find a god!'")
        return true
    end
    holding = 8
elseif stage == 5 then
    lesson = "<b:yellow>RESTING</> and <b:yellow>MONEY</>"
    holding = 10
    direction = "east"
elseif stage == 6 then
    lesson = "<b:yellow>LEVELING</>"
    holding = 10
    direction = "east"
end
actor:send(tostring(self.name) .. " tells you, 'You are taking lessons on " .. tostring(lesson) .. ".")
actor:send("Tutorial commands will appear <b:green>in green text</>.")
actor:send("Type those phrases <b:green>exactly</> as they appear to advance.")
actor:send("Remember, <b:green>spelling matters!!!</>.'")
actor:send(tostring(self.name) .. " escorts you into the Academy.")
actor:send("</>")
actor:send(tostring(self.name) .. " tells you, 'You can say <magenta>EXIT</> at any time to leave.'")
actor:teleport(get_room(519, holding))
get_room(519, holding):at(function()
    actor:command(direction)
end)
if stage == 1 then
    self:command("close gates")
    self:command("lock gates")
end$trig$, 'a533a5018732d8acb74499102cddf013'),
  -- data/triggers/534/534_02_slip_on_trail.lua
  (534, 2, $trig$-- Converted from DG Script #53402: slip_on_trail
-- Original: WORLD trigger, flags: PREENTRY, probability: 5%

-- 5% chance to trigger
if not percent_chance(5) then
    return true
end
wait(0.2)
local rnd = self.room.actors[random(1, #self.room.actors)]
-- this trigger is in multiple rooms, socheck we are in right one
if rnd.room.zone_id == actor.room.zone_id and rnd.room.local_id == actor.room.local_id then
    -- check for flying first...
    if not (rnd:has_effect(Effect.Flying)) then
        local dam = 0
        rnd:send("You slip on the icy path and fall!")
        self.room:send_except(rnd, tostring(rnd.name) .. " slips and falls!")
        -- DG compared the room vnum to 53527-53530: zone 534, ids 127-130 (the rooms
        -- this trigger is attached to). Rooms are compared by (zone_id, local_id).
        local rzone = actor.room.zone_id
        local rid = actor.room.local_id
        -- The DG cases fall through (no break): each room adds its own damage and
        -- every lower room's, so the top of the trail is 100 + 75 + 50 + 25.
        if rzone == 534 and rid == 130 then
            dam = dam + 100 + 75 + 50 + 25
        elseif rzone == 534 and rid == 129 then
            dam = dam + 75 + 50 + 25
        elseif rzone == 534 and rid == 128 then
            dam = dam + 50 + 25
        elseif rzone == 534 and rid == 127 then
            dam = dam + 25
        end
        rnd:teleport(get_room(534, 17))
        local damage_dealt = rnd:damage(dam)  -- type: physical
        get_room(534, 17):at(function()
            -- rnd looks around
        end)
        get_room(534, 17):at(function()
            self.room:send_except(rnd, tostring(rnd.name) .. " comes tumbling down the ice trail from the east.")
        end)
    end
end$trig$, '2e5a1f3ad4d9a25852fc9279190d5021'),
