  -- data/triggers/553/553_03_phase_1_cleric_accept.lua
  (553, 3, $trig$-- Converted from DG Script #55303: Phase_1_cleric_accept
-- Original: MOB trigger, flags: SPEECH_TO, probability: 100%
-- DG word list (num_arg 100): the speech must contain one of these as a whole word or phrase.
local speech_padded = " " .. string.lower(speech) .. " "
local speech_hit = false
for _, w in ipairs({"yes", "armor", "quests", "quest", "hello", "hi"}) do
    if string.find(speech_padded, "[%s%p]" .. string.gsub(w, "%p", "%%%0") .. "[%s%p]") then
        speech_hit = true
        break
    end
end
if not speech_hit then
    return true  -- None of the listed words
end

-- 
-- This will recognize the acceptance of the phase armor quest
-- by a cleric and set the quest variable for later interaction.
-- 
-- This is for clerics only
