if CLERIC_SUB then
    wait(0.2)
    if actor:get_quest_stage("phase_armor") == 0 then
        actor:start_quest("phase_armor")
    end
    actor:send(tostring(self.name) .. " tells you, \"Excellent, I can make nice [<b:white>boots</>], a [<b:white>helm</>], [<b:white>gauntlets</>],\"")
