        wait(1)
        self:say("A servant of Nature!")
        wait(1)
        self.room:send(tostring(self.name) .. " says, 'You certainly have promise.  But you're too")
        self.room:send("</>inexperienced to act as Nature's Avenger.  Come back when you're ready for the")
        self.room:send("</>darkest of dreams.'")
    end
end$trig$, '49dddf16379169f50af9ab21487a46ef'),
  -- data/triggers/615/615_55_creeping_doom_logging_camp_drop.lua
  (615, 55, $trig$-- Converted from DG Script #61555: creeping_doom_logging_camp_drop
-- Original: WORLD trigger, flags: DROP, probability: 100%
if object.zone_id == 615 and object.local_id == 18 then
    wait(0.1)
    world.destroy(object)
    if actor:get_quest_stage("creeping_doom") == 4 then
        actor:advance_quest("creeping_doom")
    end
    self.room:send("<b:black>The " .. tostring(objects.template(615, 18).name) .. " bursts open in a flood of insects!</>")
    wait(0.2)
    zone.echo(87, "<b:black>An endless wave of crawling </><red>arachnoids<b:black> and </><green>insects<b:black> pours through the camp consuming everything in sight!</>")
    wait(1)
    zone.echo(87, "<b:black>Screams pierce the quiet of the camp as everything is swallowed by a blanket of death!</>")

    -- Spared NPCs in the camp (zone 87 mob locals).
    local spare = { [8] = true, [10] = true, [11] = true, [14] = true }
    for local_id = 3, 59 do
        local r = get_room(87, local_id)
        if r and r.actors then
            for _, person in ipairs(r.actors) do
                if person.is_npc and not spare[person.local_id] then
                    r:at(function()
                        person:damage(5000)
                        r:send("<b:black>An endless wave of crawling </><red>arachnoids<b:black> and </><green>insects<b:black> consumes " .. tostring(person.name) .. "!</>")
                    end)
                    zone.echo(87, "Someone screams as he is consumed by an endless wave of crawling <red>arachnoids</> and <green>insects</>!")
                end
            end
        end
        wait(0.2)
    end
    zone.echo(87, "<b:black>Eerie silence falls over the camp as the deluge of death subsides...</>")
end$trig$, '31f07492877d6600a004160b2c51d119'),
  -- data/triggers/615/615_99_lighting_a_roman_candle.lua
  (615, 99, $trig$-- Converted from DG Script #61599: Lighting a roman candle
-- Original: OBJECT trigger, flags: COMMAND, probability: 7%

-- Command filter: light
if not (cmd == "light") then
    return true  -- Not our command
end
local _return_value = false  -- Default: block the command (legacy script_driver ret_val = 1)
-- switch on cmd
if cmd == "l" then
    _return_value = true
    return _return_value
end
-- Argument should match this candle. Accept any string.find match against
-- the object's keywords.
if arg and #arg > 0 and string.find(string.lower(self.shortdesc or ""), string.lower(arg)) then
    if globals.burning == 1 then
        _return_value = false
        actor:send("It's already lit!")
    elseif globals.on_ground == 0 then
        _return_value = false
        actor:send("To avoid being horribly disfigured by fire, dropping it first might be a good idea.")
    else
        _return_value = false
        globals.burning = 1
        self.room:send_except(actor, tostring(actor.name) .. " lights " .. tostring(self.shortdesc) .. ".")
        actor:send("You light " .. tostring(self.shortdesc) .. ".")
        wait(2)
        self.room:send("A few small sparks begin flying up out of " .. tostring(self.shortdesc) .. ".")
        wait(1)
        local sparks = {
            tostring(self.shortdesc) .. " sends up a shower of <yellow>brilliant <blue>golden<white> sparks</>!",
            "A blazing stream of <b:red>crimson</> and <b:green>vermillion<white> sparks</> shoots out of " .. tostring(self.shortdesc) .. "!",
            "A brilliant river of <blue>shining <b:blue>blue</> and <b:yellow>yellow</> <blue>motes</> streams out of " .. tostring(self.shortdesc) .. "!",
            "Multitudes of brightly <red>bu<yellow>rn<red>in<yellow>g <b:black>s</><blue>p</><b:black>a</><blue>r</><b:black>k</><blue>s</> shoot up into the sky from " .. tostring(self.shortdesc) .. "!",
            tostring(self.shortdesc) .. " lets loose with an impressive surge of <b:white>white</> and <b:blue>blue</> <blue>stars</>!",
            "A stream of <b:red>m<yellow>u<blue>l<magenta>t<green>i<cyan>c<yellow>o<red>l<blue>o<green>r<magenta>e<yellow>d</> <blue>sparks</> is surging up out of " .. tostring(self.shortdesc) .. "!",
        }
        local counter = 10
        while counter > 0 do
            self.room:send(sparks[random(1, #sparks)])
            wait(1)
            counter = counter - 1
        end
        wait(1)
        self.room:send(tostring(self.shortdesc) .. " shoots out a few sputtering sparks.")
        wait(0.3)
        self.room:send(tostring(self.shortdesc) .. " quietly burns out.")
        world.destroy(self.name)
    end
else
    _return_value = true
end
return _return_value$trig$, '270ecd72b6ea9d525e12f230f9d3dd6d'),
  -- data/triggers/625/625_04_ursa_s_room.lua
  (625, 4, $trig$-- Converted from DG Script #62504: ursa's room
-- Original: WORLD trigger, flags: GLOBAL, probability: 100%
--
-- Called from 625_09 (Ursa's GREET/FIGHT). `self` is the room.
-- Ursa lets out a roar; everyone in the room except Ursa
-- takes damage scaled to their level. Rangers and druids are
-- invigorated rather than hurt; Ursa himself (mild form 62507
-- and enraged form 62550) is exempt; high-level (>=100) chars
-- are exempt as well.
local ursa = self.room:find_actor("Ursa")
self.room:send_except(ursa, "<b:black>Ursa makes your frame quake with a vicious <red>ROOOOOAAAAAARRRRRR!</>")
for _, target in ipairs(self.actors) do
    local is_ursa = (target.zone_id == 625 and (target.local_id == 7 or target.local_id == 50))
    if not is_ursa and target.level < 100 then
        local dam = math.floor(1.5 * target.level - random(1, 12))
        if target.class == "ranger" or target.class == "druid" then
            target:send("<yellow>Ursa's roar invigorates your wild spirit!<b:yellow></> (<b:red>0</>)")
            self.room:send_except(target, "<yellow>Ursa's roar invigortates " .. tostring(target.name) .. "'s wild spirit!</> (<b:red>0</>)")
        else
            local damage_dealt = target:damage(dam)  -- type: physical
            target:send("<b:yellow>You shrink in pain at Ursa's mighty roar!</> (<b:red>" .. tostring(damage_dealt) .. "</>)")
            self.room:send_except(target, "<yellow>Ursa's roar causes " .. tostring(target.name) .. " to shrink in pain.</> (<blue>" .. tostring(damage_dealt) .. "</>)")
        end
    end
end$trig$, 'fce2c0522a04699a95e46550d1ac4241'),
